17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Objects;
24	import java.util.function.Function;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
46	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
47	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
48	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final TelephoneNormalizer telephoneNormalizer;
75	
76	    private final AddressNormalizer addressNormalizer;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper,
82	                                 TelephoneNormalizer telephoneNormalizer,
83	                                 AddressNormalizer addressNormalizer) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.telephoneNormalizer = telephoneNormalizer;
89	        this.addressNormalizer = addressNormalizer;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
121	        rejectBlankOwnerFields(ownerFieldsDto);
122	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
123	        if (!sharesHousehold) {
124	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
125	        }
126	        rejectCityAtCapacity(ownerFieldsDto.getCity());
127	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
128	        rejectDuplicateTelephone(normalizedTelephone);
129	        ownerFieldsDto.setTelephone(normalizedTelephone);
130	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
131	        HttpHeaders headers = new HttpHeaders();
132	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
133	        if (owner.getRegistrationDate() == null) {
134	            owner.setRegistrationDate(LocalDate.now());
135	        }
136	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
137	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
138	        if (sharesHousehold) {
139	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
140	        }
141	        this.clinicService.saveOwner(owner);
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
151	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
152	        if (currentOwner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        currentOwner.setAddress(ownerFieldsDto.getAddress());
156	        currentOwner.setCity(ownerFieldsDto.getCity());
157	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
158	        currentOwner.setLastName(ownerFieldsDto.getLastName());
159	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
160	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
161	        this.clinicService.saveOwner(currentOwner);
162	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Transactional
167	    @Override
168	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        this.clinicService.deleteOwner(owner);
174	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        HttpHeaders headers = new HttpHeaders();
185	        Pet pet = petMapper.toPet(petFieldsDto);
186	        owner.setId(ownerId);
187	        pet.setOwner(owner);
188	        pet.getType().setName(null);
189	        this.clinicService.savePet(pet);
190	        PetDto petDto = petMapper.toPetDto(pet);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
192	            .buildAndExpand(pet.getId()).toUri());
193	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
199	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
200	        if (currentOwner != null) {
201	            Pet currentPet = this.clinicService.findPetById(petId);
202	            if (currentPet != null) {
203	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
204	                currentPet.setName(petFieldsDto.getName());
205	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
206	                this.clinicService.savePet(currentPet);
207	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	            }
209	        }
210	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	    }
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
216	        HttpHeaders headers = new HttpHeaders();
217	        Visit visit = visitMapper.toVisit(visitFieldsDto);
218	        Pet pet = new Pet();
219	        pet.setId(petId);
220	        visit.setPet(pet);
221	        this.clinicService.saveVisit(visit);
222	        VisitDto visitDto = visitMapper.toVisitDto(visit);
223	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
224	            .buildAndExpand(visit.getId()).toUri());
225	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
226	    }
227	
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
232	        Owner owner = this.clinicService.findOwnerById(ownerId);
233	        if (owner != null) {
234	            Pet pet = owner.getPet(petId);
235	            if (pet != null) {
236	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
241	
242	    /**
243	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
244	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
245	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
246	     * blank (e.g. {@code "   "}). The offending field names are reported through an
247	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
248	     * as a 400 response carrying an {@code errors} array of field names.
249	     *
250	     * @param ownerFieldsDto the submitted owner fields
251	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
252	     */
253	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
254	        List<String> blankFields = new ArrayList<>();
255	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
256	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
257	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
258	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
259	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
260	        if (!blankFields.isEmpty()) {
261	            throw new InvalidOwnerFieldsException(blankFields);
262	        }
263	    }
264	
265	    private void addIfBlank(List<String> blankFields, String field, String value) {
266	        if (value != null && value.isBlank()) {
267	            blankFields.add(field);
268	        }
269	    }
270	
271	    /**
272	     * Normalizes an owner's optional email address. When present it is stored and returned
273	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
274	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
275	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
276	     * method runs.
277	     *
278	     * @param email the raw email value from the request, or {@code null} when omitted
279	     * @return the lower-cased email, or {@code null} when none was supplied
280	     */
281	    private String normalizeEmail(String email) {
282	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
283	    }
284	
285	    /**
286	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
287	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
288	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
289	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
290	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
291	     *
292	     * @param city the city of the owner being created
293	     * @param lastName the last name of the owner being created
294	     * @return the formatted customer code
295	     */
296	    private String nextCustomerCode(String city, String lastName) {
297	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
298	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
299	        long sequence = this.clinicService.findAllOwners().stream()
300	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
301	            .count() + 1L;
302	        return String.format("%s-%s-%04d", city3, last3, sequence);
303	    }
304	
305	    /**
306	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
307	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
308	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
309	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
310	     * new owner and surfaced as the read-only {@code namesakeCount} field.
311	     *
312	     * @param firstName the first name of the owner being created
313	     * @param lastName the last name of the owner being created
314	     * @return the number of existing owners with the same first and last name (case-insensitive)
315	     */
316	    private int namesakeCount(String firstName, String lastName) {
317	        return (int) this.clinicService.findAllOwners().stream()
318	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
319	                && equalsIgnoreCase(owner.getLastName(), lastName))
320	            .count();
321	    }
322	
323	    private boolean equalsIgnoreCase(String a, String b) {
324	        return a == null ? b == null : a.equalsIgnoreCase(b);
325	    }
326	
327	    /**
328	     * The maximum number of owners a single city may contain. Once a city already holds this many
329	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
330	     */
331	    private static final long MAX_OWNERS_PER_CITY = 50L;
332	
333	    /**
334	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
335	     * owners. Existing owners are matched to the requested city case-insensitively (using
336	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
337	     * the per-city counting used for the customer code. A city at capacity is reported through an
338	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
339	     * 409 Conflict response.
340	     *
341	     * @param city the city of the owner being created
342	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
343	     */
344	    private void rejectCityAtCapacity(String city) {
345	        long owners = this.clinicService.findAllOwners().stream()
346	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
347	            .count();
348	        if (owners >= MAX_OWNERS_PER_CITY) {
349	            throw new OwnerCityAtCapacityException(city);
350	        }
351	    }
352	
353	    /**
354	     * Rejects a create request whose normalized telephone is already used by any existing owner.
355	     * Existing owners' telephones are reduced to the same canonical form (via
356	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
357	     * only in formatting still collide. A collision is reported through a
358	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
359	     * as a 409 Conflict response.
360	     *
361	     * @param normalizedTelephone the canonical telephone of the owner being created
362	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
363	     */
364	    private void rejectDuplicateTelephone(String normalizedTelephone) {
365	        boolean duplicate = existingOwnerMatches(
366	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
367	            normalizedTelephone);
368	        if (duplicate) {
369	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
370	        }
371	    }
372	
373	    /**
374	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
375	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
376	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
377	     * and the owner being created to the same canonical key and reject a match.
378	     *
379	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
380	     * @param key the canonical key of the owner being created
381	     * @return {@code true} if some existing owner shares the key
382	     */
383	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
384	        return this.clinicService.findAllOwners().stream()
385	            .map(keyExtractor)
386	            .filter(Objects::nonNull)
387	            .anyMatch(key::equals);
388	    }
389	
390	    /**
391	     * Rejects a create request that shares a household with an existing owner: another owner already
392	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
393	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
394	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
395	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
396	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
397	     * check when the request opts in via {@code sharesHousehold}.
398	     *
399	     * @param lastName the last name of the owner being created
400	     * @param address the address of the owner being created
401	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
402	     */
403	    private void rejectDuplicateHousehold(String lastName, String address) {
404	        String canonicalLastName = canonicalizeHousehold(lastName);
405	        String canonicalAddress = canonicalizeHousehold(address);
406	        if (canonicalLastName == null || canonicalAddress == null) {
407	            return;
408	        }
409	        boolean duplicate = this.clinicService.findAllOwners().stream()
410	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
411	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
412	        if (duplicate) {
413	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
414	        }
415	    }
416	
417	    /**
418	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
419	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
420	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
421	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
422	     *
423	     * @param value the raw field value, or {@code null}
424	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
425	     */
426	    private String canonicalizeHousehold(String value) {
427	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
428	    }
429	
430	    /**
431	     * Derives the stable, shared {@code householdId} for an owner joining a household via
432	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
433	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
434	     * owner with the same last name at the same address - regardless of casing or spacing - is
435	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
436	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
437	     *
438	     * @param lastName the last name of the owner being created
439	     * @param address the address of the owner being created
440	     * @return the shared household identifier
441	     */
442	    private String householdId(String lastName, String address) {
443	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
444	        try {
445	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
446	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
447	            StringBuilder sb = new StringBuilder(digest.length * 2);
448	            for (byte b : digest) {
449	                sb.append(String.format("%02X", b));
450	            }
451	            return sb.substring(0, 16);
452	        } catch (java.security.NoSuchAlgorithmException e) {
453	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
454	        }
455	    }
456	}
