35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_TELEPHONE = "The telephone number is already used by another owner";
57	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the same last name and address already exists";
58	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
59	
60	    /**
61	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
62	     * class.
63	     *
64	     * @param e     Object referring to the thrown exception.
65	     * @param status HTTP response status.
66	     * @param url URL request.
67	     */
68	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
69	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
70	        problemDetail.setType(URI.create(url.toString()));
71	        problemDetail.setTitle(e.getClass().getSimpleName());
72	        problemDetail.setDetail(detail);
73	        problemDetail.setProperty("timestamp", Instant.now());
74	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
75	        return problemDetail;
76	    }
77	
78	    /**
79	     * Builds a 409 Conflict response for a create request that collides with an existing owner. The
80	     * body is a {@link ProblemDetail} carrying {@code detail} and an {@code errors} array naming the
81	     * conflicting fields, matching the shape produced for the other owner-creation error responses.
82	     *
83	     * @param e Object referring to the thrown exception.
84	     * @param request {@link HttpServletRequest} object referring to the current request.
85	     * @param detail the human-readable detail message.
86	     * @param errors the names of the fields whose values conflicted.
87	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
88	     */
89	    private ResponseEntity<ProblemDetail> conflict(Exception e, HttpServletRequest request, String detail, List<String> errors) {
90	        HttpStatus status = HttpStatus.CONFLICT;
91	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
92	        problemDetail.setProperty("errors", errors);
93	        return ResponseEntity.status(status).body(problemDetail);
94	    }
95	
96	    /**
97	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
98	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
99	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
100	     * would catch it and report an authorization failure as a 500.
101	     *
102	     * @param e The {@link AccessDeniedException} to propagate
103	     * @throws AccessDeniedException always
104	     */
105	    @ExceptionHandler(AccessDeniedException.class)
106	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
107	        throw e;
108	    }
109	
110	    /**
111	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
112	     *
113	     * @param e The {@link Exception} to be handled
114	     * @param request {@link HttpServletRequest} object referring to the current request.
115	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
116	     */
117	    @ExceptionHandler(Exception.class)
118	    @ResponseBody
119	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
120	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
121	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
128	     * method returns a 404 Not Found status if an entity does not exist.
129	     *
130	     * @param e The {@link DataIntegrityViolationException} to be handled
131	     * @param request {@link HttpServletRequest} object referring to the current request.
132	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
133	     */
134	    @ExceptionHandler(DataIntegrityViolationException.class)
135	    @ResponseBody
136	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
137	        logger.warn("Data integrity violation at {} {}: {}",
138	            request.getMethod(),
139	            request.getRequestURI(),
140	            e.getMessage());
141	        logger.debug("Data integrity violation stacktrace", e);
142	        HttpStatus status = HttpStatus.NOT_FOUND;
143	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
144	        return ResponseEntity.status(status).body(detail);
145	    }
146	
147	    /**
148	     * Handles exception thrown by Bean Validation on controller methods parameters
149	     *
150	     * @param e The {@link MethodArgumentNotValidException} to be handled
151	     * @param request {@link HttpServletRequest} object referring to the current request.
152	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
153	     */
154	    @ExceptionHandler(MethodArgumentNotValidException.class)
155	    @ResponseBody
156	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
157	        HttpStatus status = HttpStatus.BAD_REQUEST;
158	        BindingErrorsResponse errors = new BindingErrorsResponse();
159	        BindingResult bindingResult = e.getBindingResult();
160	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
161	        if (bindingResult.hasErrors()) {
162	            errors.addAllErrors(bindingResult);
163	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
164	                .map(FieldError::getField)
165	                .distinct()
166	                .toList();
167	            detail.setProperty("errors", invalidFields);
168	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
169	                .map(fieldError -> {
170	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
171	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
172	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
173	                        fieldError.getField(),
174	                        defaultMessage,
175	                        rejectedValue);
176	                    return new ValidationMessageDto(message)
177	                        .putAdditionalProperty("field", fieldError.getField())
178	                        .putAdditionalProperty("rejectedValue", rejectedValue)
179	                        .putAdditionalProperty("defaultMessage", defaultMessage);
180	                })
181	                .toList();
182	            logger.debug("Validation error at {} {}: {}",
183	                request.getMethod(),
184	                request.getRequestURI(),
185	                bindingResult.getFieldErrors());
186	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
187	            return ResponseEntity.status(status).body(detail);
188	        }
189	        return ResponseEntity.status(status).body(detail);
190	    }
191	
192	    /**
193	     * Handles {@link InvalidOwnerFieldsException} raised when an owner has required fields that are
194	     * present but blank (whitespace-only). Returns a 400 Bad Request whose body carries an
195	     * {@code errors} array listing the name of each blank field, mirroring the shape produced for
196	     * Bean Validation failures.
197	     *
198	     * @param e The {@link InvalidOwnerFieldsException} to be handled
199	     * @param request {@link HttpServletRequest} object referring to the current request.
200	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
201	     */
202	    @ExceptionHandler(InvalidOwnerFieldsException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
205	        HttpStatus status = HttpStatus.BAD_REQUEST;
206	        logger.debug("Blank owner fields at {} {}: {}",
207	            request.getMethod(),
208	            request.getRequestURI(),
209	            e.getFields());
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
211	        detail.setProperty("errors", e.getFields());
212	        return ResponseEntity.status(status).body(detail);
213	    }
214	
215	    /**
216	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner submitted to the create
217	     * endpoint has a normalized telephone that is already used by another existing owner. Returns a
218	     * 409 Conflict.
219	     *
220	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
221	     * @param request {@link HttpServletRequest} object referring to the current request.
222	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
223	     */
224	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
225	    @ResponseBody
226	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
227	        logger.debug("Duplicate owner telephone at {} {}: {}",
228	            request.getMethod(),
229	            request.getRequestURI(),
230	            e.getTelephone());
231	        return this.conflict(e, request, ERROR_DUPLICATE_TELEPHONE, List.of("telephone"));
232	    }
233	
234	    /**
235	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner submitted to the create
236	     * endpoint shares a household with an existing owner (same last name and address) without opting
237	     * in via {@code sharesHousehold}. Returns a 409 Conflict.
238	     *
239	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
240	     * @param request {@link HttpServletRequest} object referring to the current request.
241	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
242	     */
243	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
244	    @ResponseBody
245	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
246	        logger.debug("Duplicate owner household at {} {}: {}, {}",
247	            request.getMethod(),
248	            request.getRequestURI(),
249	            e.getLastName(),
250	            e.getAddress());
251	        return this.conflict(e, request, ERROR_DUPLICATE_HOUSEHOLD, List.of("lastName", "address"));
252	    }
253	
254	    /**
255	     * Handles {@link OwnerCityAtCapacityException} raised when an owner submitted to the create
256	     * endpoint would be placed in a city that already contains the maximum number of owners (50 or
257	     * more). Returns a 409 Conflict.
258	     *
259	     * @param e The {@link OwnerCityAtCapacityException} to be handled
260	     * @param request {@link HttpServletRequest} object referring to the current request.
261	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
262	     */
263	    @ExceptionHandler(OwnerCityAtCapacityException.class)
264	    @ResponseBody
265	    public ResponseEntity<ProblemDetail> handleOwnerCityAtCapacityException(OwnerCityAtCapacityException e, HttpServletRequest request) {
266	        logger.debug("Owner city at capacity at {} {}: {}",
267	            request.getMethod(),
268	            request.getRequestURI(),
269	            e.getCity());
270	        return this.conflict(e, request, ERROR_CITY_AT_CAPACITY, List.of("city"));
271	    }
